const body = $input.first().json.body;
const action = body.action; // 'create' or 'update'
const data = body.data;
const issue = data.issue || {};

// Build issue URL
const issueUrl = issue.url || `https://linear.app/bunluxsa/issue/${issue.identifier}`;
const issueTitle = issue.title || 'Unknown Issue';
const issueId = issue.identifier || issue.id || 'Unknown';

// Comment content
const commentBody = data.body || '';
const commentUser = data.user?.name || 'Someone';

// Detect if comment contains image URLs
const imageRegex = /!\[.*?\]\((https?:\/\/[^\s)]+)\)/g;
const urlRegex = /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g;

let cleanComment = commentBody;
const imageUrls = [];
const linkMatches = [];

// Extract images
let imgMatch;
while ((imgMatch = imageRegex.exec(commentBody)) !== null) {
  imageUrls.push(imgMatch[1]);
  cleanComment = cleanComment.replace(imgMatch[0], `📎 [Image](${imgMatch[1]})`);
}

// Extract links
let linkMatch;
while ((linkMatch = urlRegex.exec(commentBody)) !== null) {
  linkMatches.push({ text: linkMatch[1], url: linkMatch[2] });
}

// Remove markdown formatting for display
cleanComment = cleanComment
  .replace(/\*\*(.+?)\*\*/g, '**$1**')
  .replace(/^#+\s/gm, '')
  .trim();

// Truncate if too long
if (cleanComment.length > 1000) {
  cleanComment = cleanComment.substring(0, 997) + '...';
}

// Color: purple (matches TMS Lite brand #7c2dc7)
const color = 8073671; // #7B2DC7 in decimal

// Build embed fields
const fields = [
  {
    name: '🎫 Issue',
    value: `[${issueId}: ${issueTitle}](${issueUrl})`,
    inline: false
  }
];

if (issue.assignee?.name) {
  fields.push({
    name: '👤 Assignee',
    value: issue.assignee.name,
    inline: true
  });
}

if (issue.state?.name) {
  fields.push({
    name: '📊 Status',
    value: issue.state.name,
    inline: true
  });
}

if (issue.priority !== undefined) {
  const priorityMap = { 0: 'No Priority', 1: '🔴 Urgent', 2: '🟠 High', 3: '🟡 Medium', 4: '🔵 Low' };
  fields.push({
    name: '⚡ Priority',
    value: priorityMap[issue.priority] || 'Unknown',
    inline: true
  });
}

// Build Discord payload
const payload = {
  embeds: [
    {
      author: {
        name: `💬 ${commentUser} commented`
      },
      description: cleanComment || '*(empty comment)*',
      color: color,
      fields: fields,
      footer: {
        text: `Linear • ${action === 'create' ? 'New Comment' : 'Comment Updated'}`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

// If there's an image, add it to embed
if (imageUrls.length > 0) {
  payload.embeds[0].image = { url: imageUrls[0] };
  // If more than 1 image, mention in footer
  if (imageUrls.length > 1) {
    payload.embeds[0].footer.text += ` • ${imageUrls.length} images attached`;
  }
}

return { payload: JSON.stringify(payload) };
